"use client";

import { useEffect } from "react";

const referenceMarkup = "\n\n<!-- NAV -->\n<nav>\n  <div class=\"nav-inner\">\n    <a class=\"logo\" href=\"#\">\n      <div class=\"logo-icon\">\n        <svg width=\"22\" height=\"22\" viewBox=\"0 0 22 22\" fill=\"none\">\n          <path d=\"M11 3L3 9.5V19H8.5V14H13.5V19H19V9.5L11 3Z\" fill=\"#5BA891\" opacity=\"0.2\"/>\n          <path d=\"M11 3L3 9.5V19H8.5V14H13.5V19H19V9.5L11 3Z\" stroke=\"#5BA891\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/>\n          <circle cx=\"17\" cy=\"5\" r=\"2.5\" fill=\"#F0B8B8\"/>\n        </svg>\n      </div>\n      <div>\n        <div class=\"logo-name\">japan life support</div>\n        <div class=\"logo-tagline\">Life in Japan, gently shared</div>\n      </div>\n    </a>\n    <ul class=\"nav-links\">\n      <li><a href=\"#about\">Giới Thiệu</a></li>\n      <li><a href=\"#posts\">Kinh Nghiệm Sống</a></li>\n      <li><a href=\"#sale\">Săn Sale</a></li>\n      <li><a href=\"#consult\">Góc Tư Vấn</a></li>\n      <li><a href=\"#faq\">FAQ</a></li>\n      <li><a href=\"#contact\">Liên Hệ</a></li>\n      <li><a href=\"#contact\" class=\"nav-cta\">Hỏi đáp cùng Phương</a></li>\n    </ul>\n    <!-- Social icons -->\n    <div class=\"nav-social\">\n      <!-- Facebook -->\n      <a href=\"https://facebook.com/YOUR_FB\" target=\"_blank\" rel=\"noopener\" class=\"fb\" title=\"Facebook của Phương\">\n        <svg viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M24 12.073C24 5.405 18.627 0 12 0S0 5.405 0 12.073C0 18.1 4.388 23.094 10.125 24v-8.437H7.078v-3.49h3.047V9.41c0-3.025 1.792-4.697 4.533-4.697 1.312 0 2.686.236 2.686.236v2.97h-1.513c-1.491 0-1.956.93-1.956 1.886v2.268h3.328l-.532 3.49h-2.796V24C19.612 23.094 24 18.1 24 12.073z\"/></svg>\n      </a>\n      <!-- TikTok -->\n      <a href=\"https://tiktok.com/@YOUR_TIKTOK\" target=\"_blank\" rel=\"noopener\" class=\"tt\" title=\"TikTok của Phương\">\n        <svg viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M19.59 6.69a4.83 4.83 0 0 1-3.77-4.25V2h-3.45v13.67a2.89 2.89 0 0 1-2.88 2.5 2.89 2.89 0 0 1-2.89-2.89 2.89 2.89 0 0 1 2.89-2.89c.28 0 .54.04.79.1V9.01a6.33 6.33 0 0 0-.79-.05 6.34 6.34 0 0 0-6.34 6.34 6.34 6.34 0 0 0 6.34 6.34 6.34 6.34 0 0 0 6.33-6.34V8.75a8.2 8.2 0 0 0 4.78 1.52V6.82a4.85 4.85 0 0 1-1.01-.13z\"/></svg>\n      </a>\n    </div>\n  </div>\n</nav>\n\n<!-- HERO — artistic Japanese style -->\n<div class=\"hero-wrap\">\n  <div class=\"hero-inner\">\n    <!-- LEFT: text on cream -->\n    <div class=\"hero-left\">\n      <div class=\"hero-badge\">Chia sẻ kinh nghiệm sống ở Nhật</div>\n      <h1>10 năm sống ở Nhật và những điều mình ước <em>có người nói sớm hơn</em></h1>\n      <p class=\"hero-desc\">Mình là Mai Phương. Từ những ngày đầu loay hoay với giấy tờ, thuế, Nenkin đến khi thạo mọi ngóc ngách săn sale và chi tiêu thông minh — trang này là nơi mình ghi lại để hành trình của bạn bớt đi những lần phải mày mò một mình.</p>\n      <div class=\"hero-actions\">\n        <a href=\"#contact\" class=\"btn-white\">Hỏi đáp cùng Phương</a>\n        <a href=\"#posts\" class=\"btn-ghost\">Kinh nghiệm sống →</a>\n      </div>\n    </div>\n    <!-- RIGHT: organic-clipped bright photos -->\n    <div class=\"hero-right\">\n      <span class=\"hero-sakura\">🌸</span>\n      <span class=\"hero-sakura2\">🌸</span>\n      <div class=\"hero-dot-1\"></div>\n      <div class=\"hero-dot-2\"></div>\n      <!-- Main photo — cherry blossom path, bright daylight -->\n      <img class=\"hero-photo-main\"\n        src=\"data:image/jpeg;base64,\"\n        alt=\"Hoa anh đào Nhật Bản\" loading=\"eager\">\n      <!-- Sub photo — Japanese street daytime -->\n      <img class=\"hero-photo-sub\"\n        src=\"data:image/jpeg;base64,\"\n        alt=\"Phố Nhật ban ngày\">\n\n    </div>\n  </div>\n</div>\n\n<!-- GIỚI THIỆU -->\n<section class=\"about-section\" id=\"about\">\n  <div class=\"section-inner\">\n    <div class=\"about-grid\">\n      <div class=\"about-img-wrap\">\n        <img src=\"data:image/jpeg;base64,\" alt=\"Cuộc sống ở Nhật\">\n\n      </div>\n      <div>\n        <span class=\"section-label\">Giới thiệu</span>\n        <h2>Góc nhỏ của Phương — 10 năm gói ghém chuyện sống ở Nhật</h2>\n        <p style=\"color:var(--text-muted);font-size:15.5px;line-height:1.8;margin-top:1rem;\">\n          Chào bạn, mình là Mai Phương. Suốt một thập kỷ tại Nhật, mình từng nếm đủ \"vị\" của cuộc sống tha hương — từ việc kẹt giữa đống thủ tục hành chính phức tạp đến những lúc loay hoay tiết kiệm từng đồng xu.\n        </p>\n        <p style=\"color:var(--text-muted);font-size:15.5px;line-height:1.8;margin-top:0.85rem;\">\n          Mình hiểu cảm giác bơ vơ khi đứng trước một tờ giấy thông báo mà không biết bắt đầu từ đâu. Vì thế, mình viết blog này không phải với tư cách một chuyên gia, mà là một người đi trước — sẵn sàng chia sẻ lại những bài học thực tế về thuế, Nenkin và cách sống thật \"chất\" với chi phí tối ưu.\n        </p>\n        <div class=\"about-quote\">\n          Mình sống ở Nhật 10 năm, tự xoay xở qua đủ thứ — giấy tờ, thuế, Nenkin, chuyển nhà — nhiều lần không biết hỏi ai. Những gì mình mày mò được, mình viết lại ở đây để bạn đỡ mất công đi tìm từ đầu.\n        </div>\n\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- TOPICS -->\n<section class=\"topics-section\" id=\"topics\">\n  <div class=\"section-inner\">\n    <span class=\"section-label\">Bạn Có Thể Hỏi Mình Về</span>\n    <h2>Những việc thường gặp khi sống ở Nhật</h2>\n    <p class=\"section-desc\">Mình không biết tất cả, nhưng 10 năm qua đủ để hiểu những \"nút thắt\" phổ biến nhất. Đây là những chủ đề mình tự tin có thể cùng bạn tháo gỡ.</p>\n    <div class=\"topics-grid\">\n      <a class=\"topic-card\" href=\"#posts\"><div class=\"topic-icon\" style=\"background:#E8F5F0\">📋</div><h3>Nenkin</h3><p>Cần chuẩn bị gì, nên kiểm tra điều kiện ra sao và những điểm dễ nhầm khi làm hồ sơ.</p></a>\n      <a class=\"topic-card\" href=\"#posts\"><div class=\"topic-icon\" style=\"background:#FDF8F3\">💴</div><h3>Thuế tại Nhật</h3><p>Cách đọc giấy báo thuế, phụ thuộc gia đình, hoàn thuế và các mốc thời gian nên nhớ.</p></a>\n      <a class=\"topic-card\" href=\"#posts\"><div class=\"topic-icon\" style=\"background:#EEF0F8\">🗂️</div><h3>Gỡ rối thủ tục</h3><p>Kinh nghiệm đi kuyakusho, đổi địa chỉ, bảo hiểm, con dấu và các giấy tờ đời sống.</p></a>\n      <a class=\"topic-card\" href=\"#posts\"><div class=\"topic-icon\" style=\"background:#FDF0F0\">💰</div><h3>Tiết kiệm chi phí</h3><p>Những cách nhỏ nhưng thực tế để giảm chi phí nhà, sim, đi lại, mua sắm và ăn uống.</p></a>\n      <a class=\"topic-card\" href=\"#sale\"><div class=\"topic-icon\" style=\"background:#E8F5F0\">🏷️</div><h3>Săn Sale, khuyến mãi</h3><p>Coupon, point back và những khung giờ vàng giảm giá chỉ \"người cũ\" mới rành.</p></a>\n    </div>\n  </div>\n</section>\n\n<!-- POSTS -->\n<section class=\"posts-section\" id=\"posts\">\n  <div class=\"section-inner\">\n    <span class=\"section-label\">Cuộc sống tại Nhật</span>\n    <h2>Những mẩu chuyện nhỏ giúp cuộc sống nhẹ nhàng hơn</h2>\n    <p class=\"section-desc\">Không có những kiến thức vĩ mô — mình chỉ ghi lại các tình huống thực tế mình từng gặp. Hy vọng vài dòng này giúp bạn xử lý việc của mình nhanh hơn một chút.</p>\n    <div class=\"posts-grid\">\n\n      <a class=\"post-card\" href=\"#\">\n        <div class=\"post-thumb\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Giấy tờ thuế Nhật\">\n        </div>\n        <div class=\"post-body\">\n          <span class=\"post-tag\" style=\"background:#E8F5F0;color:#3B6D11;\">Giấy tờ</span>\n          <h3>Cách đọc giấy báo thuế và bảo hiểm cơ bản</h3>\n          <p>Những dòng nên xem trước, khoản nào hay gây nhầm và khi nào nên hỏi lại cơ quan địa phương.</p>\n          <span class=\"post-link\">Đọc tiếp nhé →</span>\n        </div>\n      </a>\n\n      <a class=\"post-card\" href=\"#\">\n        <div class=\"post-thumb\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Chuyển nhà Nhật Bản\">\n        </div>\n        <div class=\"post-body\">\n          <span class=\"post-tag\" style=\"background:#EEF0F8;color:#3C3489;\">Đời sống</span>\n          <h3>Checklist cần làm khi chuyển nhà tại Nhật</h3>\n          <p>Từ đổi địa chỉ, điện nước, bưu điện đến bảo hiểm — thứ tự dễ làm và đỡ sót nhất.</p>\n          <span class=\"post-link\">Đọc tiếp nhé →</span>\n        </div>\n      </a>\n\n      <a class=\"post-card\" href=\"#\">\n        <div class=\"post-thumb\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Tiết kiệm kiểu Nhật\">\n        </div>\n        <div class=\"post-body\">\n          <span class=\"post-tag\" style=\"background:#FDF8F3;color:#633806;\">Tiết kiệm</span>\n          <h3>Đi siêu thị tiết kiệm hơn mà không mất nhiều thời gian</h3>\n          <p>Thói quen xem giá, coupon và khung giờ giảm giá phù hợp với người đang đi làm.</p>\n          <span class=\"post-link\">Đọc tiếp nhé →</span>\n        </div>\n      </a>\n\n      <a class=\"post-card\" href=\"#\">\n        <div class=\"post-thumb\">\n          <img src=\"data:image/jpeg;base64,\" alt=\"Sim Nhật Bản\">\n        </div>\n        <div class=\"post-body\">\n          <span class=\"post-tag\" style=\"background:#FDF0F0;color:#791F1F;\">Mẹo sống</span>\n          <h3>Lưu ý khi mua sim, gửi tiền và đăng ký dịch vụ</h3>\n          <p>Các điều khoản nhỏ nên kiểm tra trước để tránh phí phát sinh hoặc hợp đồng không phù hợp.</p>\n          <span class=\"post-link\">Đọc tiếp nhé →</span>\n        </div>\n      </a>\n\n    </div>\n  </div>\n</section>\n\n<!-- SALE -->\n<section class=\"sale-section\" id=\"sale\">\n  <div class=\"section-inner\">\n    <span class=\"section-label\">Góc Săn Sale</span>\n    <!-- Ảnh konbini / cửa hàng Nhật -->\n    <img class=\"sale-banner\"\n      src=\"data:image/jpeg;base64,\"\n      alt=\"Mua sắm tại Nhật\">\n    <div class=\"sale-grid\">\n      <div>\n        <h2>Sống chất tại Nhật không nhất thiết phải đắt đỏ</h2>\n        <p style=\"color:var(--text-muted);font-size:15px;line-height:1.78;margin-bottom:1.5rem;\">\n          Sống ở Nhật lâu, mình học được cách \"luồn lách\" qua những bảng giá đắt đỏ. Mình sẽ chỉ bạn cách săn coupon, tận dụng hệ thống Point và những khung giờ vàng giảm giá tại siêu thị mà chỉ \"người cũ\" mới rành. Tiết kiệm một chút mỗi ngày là cách mình yêu chiều bản thân bền vững nhất.\n        </p>\n        <a href=\"#posts\" class=\"btn-navy\">Xem bí kíp tiết kiệm</a>\n      </div>\n      <div class=\"sale-cards\">\n        <a class=\"sale-card\" href=\"#\">\n          <div class=\"sale-card-icon\">🛒</div>\n          <div class=\"sale-card-text\"><h4>Siêu thị và drugstore</h4><p>Ghi chú nhanh các đợt giảm giá dễ dùng trong tuần.</p></div>\n          <span class=\"sale-badge\" style=\"background:#E8F5F0;color:#3B6D11;\">Sale nhẹ</span>\n        </a>\n        <a class=\"sale-card\" href=\"#\">\n          <div class=\"sale-card-icon\">🛍️</div>\n          <div class=\"sale-card-text\"><h4>Sàn thương mại điện tử</h4><p>Theo dõi coupon, point back và những ngày campaign lớn.</p></div>\n          <span class=\"sale-badge\" style=\"background:#EEF0F8;color:#3C3489;\">Đáng xem</span>\n        </a>\n        <a class=\"sale-card\" href=\"#\">\n          <div class=\"sale-card-icon\">📱</div>\n          <div class=\"sale-card-text\"><h4>Dịch vụ đời sống</h4><p>Ưu đãi sim, internet, vé đi lại và app tiện ích.</p></div>\n          <span class=\"sale-badge\" style=\"background:#FDF8F3;color:#633806;\">Mới</span>\n        </a>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- TƯ VẤN -->\n<section class=\"consult-section\" id=\"consult\">\n  <div class=\"section-inner\">\n    <span class=\"section-label\">Góc Tư Vấn</span>\n    <div class=\"consult-inner\">\n      <div>\n        <h2>Đừng ngại nhắn cho mình như một người chị, người bạn đi trước</h2>\n        <p style=\"color:var(--text-muted);font-size:15px;line-height:1.78;margin-top:0.6rem;\">\n          Mọi thắc mắc của bạn đều xứng đáng được giải đáp. Nếu bạn đang kẹt lại ở một thủ tục nào đó hay cảm thấy bối rối trước đống giấy tờ tại Nhật — mình luôn ở đây để lắng nghe. Mình sẽ chia sẻ tất cả những gì mình biết, hoặc cùng bạn tìm ra hướng giải quyết phù hợp nhất cho tình huống của bạn.\n        </p>\n        <div class=\"steps\">\n          <div class=\"step\">\n            <div class=\"step-num\">1</div>\n            <div class=\"step-body\"><h4>Bạn gửi câu hỏi</h4><p>Chỉ cần kể ngắn tình huống hiện tại. Không cần viết chuẩn hay biết thuật ngữ tiếng Nhật.</p></div>\n          </div>\n          <div class=\"step\">\n            <div class=\"step-num\">2</div>\n            <div class=\"step-body\"><h4>Mình đọc và hỏi thêm nếu cần</h4><p>Nếu còn thiếu thông tin, mình sẽ hỏi lại vài ý để tránh trả lời chung chung.</p></div>\n          </div>\n          <div class=\"step\">\n            <div class=\"step-num\">3</div>\n            <div class=\"step-body\"><h4>Bạn nhận gợi ý bước tiếp theo</h4><p>Mình trả lời theo kiểu dễ làm: nên xem giấy nào, làm gì trước và khi nào nên hỏi cơ quan phù hợp.</p></div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"form-card\" id=\"contact\">\n        <div style=\"margin-bottom:1.5rem;\">\n          <span class=\"section-label\" style=\"margin-bottom:0.4rem;\">Giải đáp miễn phí</span>\n          <h3 style=\"font-size:1.2rem;font-weight:700;color:var(--navy);\">Gửi câu hỏi cho Mai Phương</h3>\n          <p style=\"font-size:13.5px;color:var(--text-muted);margin-top:6px;\">Bạn có thể viết ngắn gọn, chưa cần đúng thuật ngữ. Mình sẽ đọc và phản hồi theo hướng dễ hiểu nhất có thể.</p>\n        </div>\n        <div class=\"form-row\">\n          <div class=\"form-group\"><label>Tên của bạn</label><input type=\"text\" placeholder=\"Ví dụ: An\"></div>\n          <div class=\"form-group\"><label>Email hoặc số điện thoại</label><input type=\"text\" placeholder=\"email@example.com\"></div>\n        </div>\n        <div class=\"form-group\">\n          <label>Bạn muốn hỏi về</label>\n          <select>\n            <option value=\"\">Chọn chủ đề</option>\n            <option>Nenkin / Bảo hiểm hưu trí</option>\n            <option>Thuế / Hoàn thuế</option>\n            <option>Gỡ rối thủ tục hành chính</option>\n            <option>Chuyển nhà / Đổi địa chỉ</option>\n            <option>Tiết kiệm chi phí</option>\n            <option>Sim / Internet / Dịch vụ</option>\n            <option>Khác</option>\n          </select>\n        </div>\n        <div class=\"form-group\">\n          <label>Câu hỏi của bạn</label>\n          <textarea placeholder=\"Bạn đang gặp tình huống gì? Có giấy tờ hoặc mốc thời gian nào cần lưu ý không?\"></textarea>\n        </div>\n        <button class=\"btn-submit\">Gửi câu hỏi miễn phí</button>\n        <p class=\"form-note\">Đừng ngại hỏi nếu bạn đang kẹt ở một tờ giấy, một dòng thông báo hoặc không biết nên bắt đầu từ đâu.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- FAQ -->\n<section class=\"faq-section\" id=\"faq\">\n  <div class=\"section-inner\" style=\"text-align:center;\">\n    <span class=\"section-label\" style=\"display:inline-block;\">FAQ</span>\n    <h2>Trước khi bạn gửi câu hỏi</h2>\n    <p class=\"section-desc\" style=\"margin:0 auto 0;\">Mình muốn bạn thấy thoải mái khi hỏi, kể cả khi cuối cùng bạn chỉ cần một gợi ý nhỏ.</p>\n    <div class=\"faq-list\">\n      <div class=\"faq-item open\">\n        <button class=\"faq-q\">Tư vấn có mất phí không?<span class=\"faq-icon\">+</span></button>\n        <p class=\"faq-a\">Miễn phí hoàn toàn. Mình không thu phí tư vấn và cũng không bán dịch vụ qua trang này. Nếu câu hỏi nằm trong phần mình biết, mình sẽ trả lời thẳng.</p>\n      </div>\n      <div class=\"faq-item\">\n        <button class=\"faq-q\">Mình có bị ép dùng dịch vụ không?<span class=\"faq-icon\">+</span></button>\n        <p class=\"faq-a\">Không. Mình không liên kết với dịch vụ nào để hưởng hoa hồng. Nếu mình có đề xuất dịch vụ bên ngoài, mình sẽ nói rõ lý do và để bạn tự quyết định.</p>\n      </div>\n      <div class=\"faq-item\">\n        <button class=\"faq-q\">Bạn có phải chuyên gia thuế hay luật sư không?<span class=\"faq-icon\">+</span></button>\n        <p class=\"faq-a\">Không. Mình chỉ là người sống ở Nhật lâu năm và chia sẻ kinh nghiệm thực tế. Những trường hợp phức tạp hoặc cần chính xác pháp lý, mình sẽ khuyên bạn đến cơ quan chức năng phù hợp.</p>\n      </div>\n      <div class=\"faq-item\">\n        <button class=\"faq-q\">Mình không rành tiếng Nhật có hỏi được không?<span class=\"faq-icon\">+</span></button>\n        <p class=\"faq-a\">Hoàn toàn được. Bạn cứ viết bằng tiếng Việt, mô tả tình huống theo cách bạn hiểu. Mình sẽ đọc và hỏi thêm nếu cần — không cần biết tên chính thức của giấy tờ hay thủ tục.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- FOOTER -->\n<footer>\n  <div class=\"footer-inner\">\n    <div>\n      <div class=\"footer-logo-name\">\n        <div class=\"footer-logo-icon\">\n          <svg width=\"16\" height=\"16\" viewBox=\"0 0 22 22\" fill=\"none\">\n            <path d=\"M11 3L3 9.5V19H8.5V14H13.5V19H19V9.5L11 3Z\" stroke=\"rgba(255,255,255,0.7)\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/>\n            <circle cx=\"17\" cy=\"5\" r=\"2.5\" fill=\"#F4C0D1\" opacity=\"0.7\"/>\n          </svg>\n        </div>\n        japan life support\n      </div>\n      <p class=\"footer-desc\">Blog cá nhân của Mai Phương về cuộc sống ở Nhật, giấy tờ, Nenkin, thuế và những mẹo tiết kiệm nhỏ mỗi ngày.</p>\n      <div class=\"footer-social\">\n        <a href=\"https://facebook.com/YOUR_FB\" target=\"_blank\" rel=\"noopener\" title=\"Facebook\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M24 12.073C24 5.405 18.627 0 12 0S0 5.405 0 12.073C0 18.1 4.388 23.094 10.125 24v-8.437H7.078v-3.49h3.047V9.41c0-3.025 1.792-4.697 4.533-4.697 1.312 0 2.686.236 2.686.236v2.97h-1.513c-1.491 0-1.956.93-1.956 1.886v2.268h3.328l-.532 3.49h-2.796V24C19.612 23.094 24 18.1 24 12.073z\"/></svg>\n        </a>\n        <a href=\"https://tiktok.com/@YOUR_TIKTOK\" target=\"_blank\" rel=\"noopener\" title=\"TikTok\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M19.59 6.69a4.83 4.83 0 0 1-3.77-4.25V2h-3.45v13.67a2.89 2.89 0 0 1-2.88 2.5 2.89 2.89 0 0 1-2.89-2.89 2.89 2.89 0 0 1 2.89-2.89c.28 0 .54.04.79.1V9.01a6.33 6.33 0 0 0-.79-.05 6.34 6.34 0 0 0-6.34 6.34 6.34 6.34 0 0 0 6.34 6.34 6.34 6.34 0 0 0 6.33-6.34V8.75a8.2 8.2 0 0 0 4.78 1.52V6.82a4.85 4.85 0 0 1-1.01-.13z\"/></svg>\n        </a>\n      </div>\n    </div>\n    <ul class=\"footer-links\">\n      <li><a href=\"#about\">Giới Thiệu</a></li>\n      <li><a href=\"#posts\">Kinh Nghiệm Sống</a></li>\n      <li><a href=\"#sale\">Săn Sale</a></li>\n      <li><a href=\"#consult\">Góc Tư Vấn</a></li>\n      <li><a href=\"#faq\">FAQ</a></li>\n      <li><a href=\"#contact\">Liên Hệ</a></li>\n    </ul>\n  </div>\n  <div class=\"footer-bottom\">© 2026 japan life support · Chia sẻ từ kinh nghiệm cá nhân · Không phải tư vấn pháp lý hay tài chính</div>\n</footer>\n\n\n";

export default function Home() {
  useEffect(() => {
    const blogSlugs = [
      "nhan-duoc-giay-nenkin-thi-phai-lam-gi",
      "giay-bao-thue-o-nhat-can-lam-gi-khi-nhan-duoc",
      "checklist-chuyen-nha-o-nhat-dung-bo-sot-buoc-nay",
      "cach-tiet-kiem-chi-phi-sinh-hoat-o-nhat-thuc-te",
      "san-sale-o-nhat-nen-xem-o-dau-truoc",
    ];
    const postCards = Array.from(document.querySelectorAll<HTMLAnchorElement>(".post-card"));
    postCards.forEach((card, index) => {
      const slug = blogSlugs[index];
      if (slug) card.href = `/blog/${slug}`;
    });

    const buttons = Array.from(document.querySelectorAll<HTMLButtonElement>(".faq-q"));
    const onClick = (event: Event) => {
      const button = event.currentTarget as HTMLButtonElement;
      const item = button.closest(".faq-item");
      if (!item) return;
      const isOpen = item.classList.contains("open");
      document.querySelectorAll(".faq-item").forEach((faqItem) => {
        faqItem.classList.remove("open");
      });
      if (!isOpen) item.classList.add("open");
    };

    buttons.forEach((button) => button.addEventListener("click", onClick));
    return () => {
      buttons.forEach((button) => button.removeEventListener("click", onClick));
    };
  }, []);

  return (
    <div
      className="site-reference"
      dangerouslySetInnerHTML={{ __html: referenceMarkup }}
    />
  );
}
